#pragma once

// Listens to OrcaSlicer's own dialogs. Every Orca dialog opens through
// DPIAware::ShowModal, which first asks answer_modal (GUI_Utils.hpp); that
// hands the dialog to the listeners registered here, innermost first. A
// listener answers the dialog, and it is never shown, or passes it on; when
// every listener has passed, Orca shows it as usual.
//
// A listener learns what the window itself shows: its title, its message and
// which of the standard buttons it offers. Nothing is matched against the
// words, which are Orca's and in the interface language.
//
// GUI thread only.

#include "Workspace.hpp"

#include <functional>
#include <optional>
#include <string>
#include <vector>

class wxWindow;

namespace Slic3r::GUI::JusPrin::Workspace {

struct DialogFacts
{
    std::string title;
    std::string text;
    bool        ok{false}, yes{false}, no{false}, cancel{false};
    // Orca's STEP import settings, recognised by type: its Cancel abandons
    // the whole load, so it is the one dialog whose least change is OK.
    bool        step_import{false};
};

DialogFacts read_dialog(wxWindow& dialog);

// The choice that changes least, from the buttons alone: No, else Cancel,
// else OK, else Yes (Orca offers a lone Yes only where it acts regardless).
// A dialog with none of them is cancelled and marked unrecognised.
OrcaMessage least_change_answer(const DialogFacts& facts, int& answer);

// A listener's answer that shows the dialog to the person, so no listener
// outside it answers: for a question that is theirs while an open or a tool
// answers everything else.
inline constexpr int kShowToPerson = -1;

class ScopedDialogListener
{
public:
    // Returns the id ShowModal would have returned, kShowToPerson, or nothing
    // to pass.
    using Listener = std::function<std::optional<int>(wxWindow& dialog, const DialogFacts& facts)>;

    explicit ScopedDialogListener(Listener listener);
    ~ScopedDialogListener();
    ScopedDialogListener(const ScopedDialogListener&)            = delete;
    ScopedDialogListener& operator=(const ScopedDialogListener&) = delete;

private:
    friend bool dispatch_dialog(wxWindow& dialog, int& answer);
    Listener              m_listener;
    ScopedDialogListener* m_outer{nullptr};
};

// Answers every dialog with the least change and writes each one down: the
// file load's listener, and the safety net around a tool's Orca calls.
class ScopedLeastChangeAnswers
{
public:
    explicit ScopedLeastChangeAnswers(bool prefer_cancel = false);
    const std::vector<OrcaMessage>& messages() const { return m_messages; }
    std::vector<OrcaMessage>        take_messages() { return std::move(m_messages); }
    void                            add_message(OrcaMessage message) { m_messages.push_back(std::move(message)); }

private:
    std::vector<OrcaMessage> m_messages;
    ScopedDialogListener     m_listener; // after m_messages, which it writes to
};

} // namespace Slic3r::GUI::JusPrin::Workspace
#include "DialogListeners.hpp"

#include "slic3r/GUI/GUI_Utils.hpp"
#include "slic3r/GUI/StepMeshDialog.hpp"

#include <wx/html/htmlwin.h>
#include <wx/stattext.h>
#include <wx/thread.h>
#include <wx/toplevel.h>
#include <wx/window.h>

namespace Slic3r::GUI::JusPrin::Workspace {

namespace {
ScopedDialogListener* g_innermost = nullptr;

// A message box's words are in a wxHtmlWindow (Orca's MsgDialog) or in
// static text; the buttons are neither.
void collect_text(wxWindow& window, wxString& text)
{
    for (wxWindow* child : window.GetChildren()) {
        if (!child->IsShown())
            continue;
        wxString part;
        if (auto* html = dynamic_cast<wxHtmlWindow*>(child))
            part = html->ToText();
        else if (const auto* label = dynamic_cast<const wxStaticText*>(child))
            part = label->GetLabel();
        part.Trim(true).Trim(false);
        if (!part.empty())
            text += (text.empty() ? "" : "\n") + part;
        collect_text(*child, text);
    }
}

constexpr size_t kMessageTextLimit = 4000; // characters
} // namespace

DialogFacts read_dialog(wxWindow& dialog)
{
    DialogFacts facts;
    if (const auto* window = dynamic_cast<const wxTopLevelWindow*>(&dialog))
        facts.title = window->GetTitle().ToUTF8().data();
    wxString text;
    collect_text(dialog, text);
    if (text.length() > kMessageTextLimit)
        text = text.Left(kMessageTextLimit) + wxString::FromUTF8("…");
    facts.text        = text.ToUTF8().data();
    facts.ok          = wxWindow::FindWindowById(wxID_OK, &dialog) != nullptr;
    facts.yes         = wxWindow::FindWindowById(wxID_YES, &dialog) != nullptr;
    facts.no          = wxWindow::FindWindowById(wxID_NO, &dialog) != nullptr;
    facts.cancel      = wxWindow::FindWindowById(wxID_CANCEL, &dialog) != nullptr;
    facts.step_import = dynamic_cast<const StepMeshDialog*>(&dialog) != nullptr;
    return facts;
}

OrcaMessage least_change_answer(const DialogFacts& facts, int& answer)
{
    OrcaMessage message;
    message.title = facts.title;
    message.text  = facts.text;
    if (facts.ok) message.buttons.emplace_back("ok");
    if (facts.yes) message.buttons.emplace_back("yes");
    if (facts.no) message.buttons.emplace_back("no");
    if (facts.cancel) message.buttons.emplace_back("cancel");

    if (facts.step_import) {
        answer         = wxID_OK;
        message.answer = "ok";
    } else if (facts.no) {
        answer         = wxID_NO;
        message.answer = "no";
    } else if (facts.cancel) {
        answer         = wxID_CANCEL;
        message.answer = "cancel";
    } else if (facts.ok) {
        answer         = wxID_OK;
        message.answer = "ok";
    } else if (facts.yes) {
        answer         = wxID_YES;
        message.answer = "yes";
    } else {
        answer             = wxID_CANCEL;
        message.answer     = "cancel";
        message.recognized = false;
    }
    return message;
}

ScopedDialogListener::ScopedDialogListener(Listener listener) : m_listener(std::move(listener)), m_outer(g_innermost)
{
    wxASSERT(wxIsMainThread());
    g_innermost = this;
}

ScopedDialogListener::~ScopedDialogListener()
{
    wxASSERT(g_innermost == this);
    g_innermost = m_outer;
}

bool dispatch_dialog(wxWindow& dialog, int& answer)
{
    if (g_innermost == nullptr || !wxIsMainThread())
        return false;
    const DialogFacts facts = read_dialog(dialog);
    for (ScopedDialogListener* listener = g_innermost; listener != nullptr; listener = listener->m_outer)
        if (const std::optional<int> decided = listener->m_listener(dialog, facts)) {
            if (*decided == kShowToPerson)
                return false;
            answer = *decided;
            return true;
        }
    return false;
}

ScopedLeastChangeAnswers::ScopedLeastChangeAnswers(bool prefer_cancel)
    : m_listener([this, prefer_cancel](wxWindow&, const DialogFacts& facts) -> std::optional<int> {
        int answer = wxID_CANCEL;
        OrcaMessage message = least_change_answer(facts, answer);
        if (prefer_cancel && facts.cancel && !facts.step_import) {
            answer = wxID_CANCEL;
            message.answer = "cancel";
        }
        m_messages.push_back(std::move(message));
        return answer;
    })
{}

} // namespace Slic3r::GUI::JusPrin::Workspace

namespace Slic3r::GUI {

bool answer_modal(wxWindow& dialog, int& answer)
{
    return JusPrin::Workspace::dispatch_dialog(dialog, answer);
}

} // namespace Slic3r::GUI
wxFont get_default_font_for_dpi(const wxWindow* window, int dpi);
inline wxFont get_default_font(const wxWindow* window) { return get_default_font_for_dpi(window, get_dpi_for_window(window)); }

bool check_dark_mode();
void update_dark_config();
#ifdef _WIN32
void update_dark_ui(wxWindow* window);
#endif

extern std::deque<wxDialog*> dialogStack;
// JusPrin: a listener registered for a stretch of work answers the dialog
// instead of showing it. False when none answers. Defined in
// JusPrin/Workspace/DialogListeners.cpp.
bool answer_modal(wxWindow& dialog, int& answer);

template<class P> class DPIAware : public P
{
public:
    DPIAware(wxWindow *parent, wxWindowID id, const wxString &title, const wxPoint &pos=wxDefaultPosition,
        const wxSize &size=wxDefaultSize, long style=wxDEFAULT_FRAME_STYLE, const wxString &name=wxFrameNameStr)
        : P(parent, id, title, pos, size, style, name)

