{
    if (m_tool_loads != 0 || m_report_scheduled || m_finished_loads.empty())
        return;
    m_report_scheduled = true;
    wxGetApp().CallAfter([this, alive = std::weak_ptr<bool>(m_alive)] {
        if (alive.lock())
            deliver_load_report();
    });
}

