13	    const Agent::ToolActivity& run_dialog_tool(const char* tool, const nlohmann::json& arguments)
14	    {
15	        Agent::AgentHost& host = project_host();
16	        std::string message_id = "dialog-routing";
17	        for (const auto& message : host.conversation())
