        // The printer panel's own tools. They exist only inside a printer
        // session, which is why they carry no in-app or MCP exposure: the
        // project conversation has no printer to add, change or connect.
        // None decides anything: the model does, from what the person says,
        // and these check its decision against the printer data and carry it
        // out. printer_connect opens a local form where the person types a
        // credential the model must never see.
        {"printer_identify",
         "Show the printers you mean",
         "You decide which printer this is. This tool checks the printers you name against the app's printer list, shows them "
         "to the person as picture cards, and returns reference details. It saves nothing: call printer_add once the person "
         "confirms one model. alreadyYours only means settings for the same model were saved before, not the same physical "
         "printer.",
         object_schema(json{{"catalogIds", {{"type", "array"}, {"items", string_schema()},
                                            {"description", "1 to 3 ids, copied exactly from the printer list."}}},
                            {"nozzle", {{"type", "number"},
                                        {"description", "Nozzle size in mm, only when the person or a photo said it."}}}},
                       json::array({"catalogIds"})),
json connection_chat_record(const std::vector<Agent::ConversationMessage>& messages, const std::vector<ToolActivity>& activities)
{
    json turns = json::array();
    for (const Agent::ConversationMessage& message : messages)
        if (!message.text.empty()) // a turn that only called a tool
            turns.push_back({{"role", message.role == Agent::MessageRole::User ? "person" :
                                      message.role == Agent::MessageRole::Note ? "app" :
                                                                                 "model"},
                             {"text", message.text}});
    json tools = json::array();
    for (const ToolActivity& activity : activities) {
        if (activity.tool != "printer_connect" && activity.tool != "printer_connection_status")
            continue;
        tools.push_back({{"tool", activity.tool},
                         {"arguments", json::parse(activity.arguments_json, nullptr, false)},
                         {"output", activity.error ? json(activity.error->code + ": " + activity.error->message) :
                                                     json::parse(activity.result_json, nullptr, false)}});
    }
    return json{{"turns", std::move(turns)}, {"tools", std::move(tools)}};
}

// -- The session's tools ----------------------------------------------------

std::optional<std::string> PrinterConversation::connection_skill() const
{
    if (!m_connect_tried)
        return std::nullopt;
    if (saved(m_printer_name).vendor_id == "BBL")
        return std::string(Agent::Protocol::SkillTrigger::kConnectBambu);
    if (m_host_type == "moonraker")
        return std::string(Agent::Protocol::SkillTrigger::kConnectMoonraker);
    if (m_host_type == "octoprint")
        return std::string(Agent::Protocol::SkillTrigger::kConnectOctoPrint);
    return std::nullopt;
}

